import csv

ШЛЯХ = "дані/контакти.csv"


def main():
    # нормалізований email -> імена контактів; dict зберігає порядок першої появи
    групи = {}
    with open(ШЛЯХ, encoding="utf-8-sig", newline="") as f:
        читач = csv.reader(f)
        next(читач, None)  # пропускаємо заголовок
        for рядок in читач:
            if not рядок:
                continue
            імʼя = рядок[0].strip() if len(рядок) > 0 else ""
            email = рядок[1].strip().lower() if len(рядок) > 1 else ""
            if not email:
                continue
            групи.setdefault(email, []).append(імʼя)

    for email, імена in групи.items():
        if len(імена) >= 2:
            print(f"email: {email}")
            for імʼя in імена:
                print(f"  {імʼя}")

    print(f"Унікальних: {len(групи)}")


if __name__ == "__main__":
    main()

